            raise AppError(f"File number not found within archive error - '{file_number}'")
        self.info = infos[file_number]
        if not (self.info.flag_bits & 0x1):
            raise AppError(
                f"Invalid zip file error - the selected file in the archive is not encrypted "
                f"(file_number:{file_number} file_name:{self.info.filename})"
            )
        self._load_local_data()
        if self.info.compress_type == 99:
            self.kind = "aes"
            self._setup_aes()
        else:
            self.kind = "zipcrypto"
            self.method = self.info.compress_type
            self.check_byte = ((self.mod_time >> 8) & 0xFF) if (self.info.flag_bits & 0x8) else ((self.info.CRC >> 24) & 0xFF)

    def _load_local_data(self):
        with open(self.zip_path, "rb") as f:
            f.seek(self.info.header_offset)
            hdr = f.read(30)
            if len(hdr) != 30 or hdr[:4] != b"PK\x03\x04":
                raise AppError("Invalid zip file error - invalid local file header")
            (sig, ver, flag, method, mod_time, mod_date, crc, comp_size, uncomp_size,
             name_len, extra_len) = struct.unpack("<IHHHHHIIIHH", hdr)
            self.mod_time = mod_time
            f.seek(name_len + extra_len, os.SEEK_CUR)
            self.encrypted_data = f.read(self.info.compress_size)

    def _setup_aes(self):
        aes = None
        extra = self.info.extra
        pos = 0
        while pos + 4 <= len(extra):
            header_id, size = struct.unpack("<HH", extra[pos:pos+4])
            data = extra[pos+4:pos+4+size]
            if header_id == 0x9901 and len(data) >= 7:
                version = struct.unpack("<H", data[:2])[0]
                vendor = data[2:4]
                strength = data[4]
                actual_method = struct.unpack("<H", data[5:7])[0]
                aes = (version, vendor, strength, actual_method)
                break
            pos += 4 + size
        if aes is None:
            raise AppError("Invalid zip file error - AES extra data not found")
        version, vendor, strength, actual_method = aes
        salt_len_map = {1: 8, 2: 12, 3: 16}
        key_len_map = {1: 16, 2: 24, 3: 32}
        if strength not in salt_len_map:
            raise AppError("Invalid zip file error - unsupported AES strength")
        salt_len = salt_len_map[strength]
        self.aes_key_len = key_len_map[strength]
        data = self.encrypted_data
        if len(data) < salt_len + 2 + 10:
            raise AppError("Invalid zip file error - invalid AES encrypted data")
        self.aes_salt = data[:salt_len]
        self.aes_verifier = data[salt_len:salt_len+2]
        self.aes_ciphertext = data[salt_len+2:-10]
        self.aes_auth = data[-10:]

    def check(self, password: str) -> bool:
        password_bytes = password.encode("utf-8", "surrogateescape")
        if self.kind == "aes":
            return self._check_aes(password_bytes)
        return self._check_zipcrypto(password_bytes)

    def _check_aes(self, password_bytes):
        key_len = self.aes_key_len
        key_material = hashlib.pbkdf2_hmac("sha1", password_bytes, self.aes_salt, 1000, 2 * key_len + 2)
        if key_material[2 * key_len:2 * key_len + 2] != self.aes_verifier:
            return False
        auth_key = key_material[key_len:2 * key_len]
        tag = hmac.new(auth_key, self.aes_ciphertext, hashlib.sha1).digest()[:10]
        return hmac.compare_digest(tag, self.aes_auth)

    def _check_zipcrypto(self, password_bytes):
        data = self.encrypted_data
        if len(data) < 12:
            return False
        keys = _zc_init_keys(password_bytes)
        header = _zc_decrypt_with_keys(keys, data[:12])
        if header[11] != self.check_byte:
            return False
        compressed = _zc_decrypt_with_keys(keys, data[12:])
        try:
            plain = _decompress_zip_member(self.method, compressed)
            if self.info.file_size is not None and len(plain) != self.info.file_size:
                return False
            return (zlib.crc32(plain) & 0xFFFFFFFF) == self.info.CRC
        except Exception:
            # The standard library knows a few ZIP compression formats; use it as a
            # slow validation fallback only after the 1-byte encryption header check.
            try:
                data = self.zf.read(self.info, pwd=password_bytes)
                return (zlib.crc32(data) & 0xFFFFFFFF) == self.info.CRC
            except Exception:
                return False


def rust_duration(ns):
    if ns < 0:
        ns = 0
    sec = ns // 1_000_000_000
    rem = ns % 1_000_000_000
    ms = rem // 1_000_000
    rem %= 1_000_000
    us = rem // 1_000
    n = rem % 1_000
    parts = []
    if sec:
        parts.append(f"{sec}s")
    if ms:
        parts.append(f"{ms}ms")
    if us:
        parts.append(f"{us}us")
    if n or not parts:
        parts.append(f"{n}ns")
    return " ".join(parts)


def read_dictionary_lines(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            s = f.read()
    except UnicodeDecodeError:
        with open(path, "rb") as f:
            s = f.read().decode("utf-8", "surrogateescape")
    if s == "":
        return []
    parts = s.split("\n")
    if s.endswith("\n"):
        parts = parts[:-1]
    return [p[:-1] if p.endswith("\r") else p for p in parts]


def try_dictionary(checker, dict_path):
    for pw in read_dictionary_lines(dict_path):
        if checker.check(pw):
            return pw
    return None


def index_in_charset(password, charset):
    base = len(charset)
    indexes = []
    for ch in password:
        # first occurrence, matching normal iteration when duplicate characters exist
        indexes.append(charset.index(ch))
    n = 0
    for idx in indexes:
        n = n * base + idx
    return n


def candidate_from_index(length, idx, charset):
    base = len(charset)
    chars = [None] * length
    for pos in range(length - 1, -1, -1):
        chars[pos] = charset[idx % base]
        idx //= base
    return "".join(chars)


def brute_force(checker, charset, min_len, max_len, starting=None):
    if len(charset) == 0:
        # The original's worker threads panic for this edge case and ultimately report not found.
        return None
    start_len = len(starting) if starting is not None else None
    for length in range(min_len, max_len + 1):
        if starting is not None:
            if length < start_len:
                continue
            start_idx = index_in_charset(starting, charset) if length == start_len else 0
        else:
            start_idx = 0
        total = len(charset) ** length
        for idx in range(start_idx, total):
            pw = candidate_from_index(length, idx, charset)
            if checker.check(pw):
                return pw
    return None


def run(opts: Options):
    validate_options(opts)
    charset = None
    if opts.passwordDictionary is None:
        charset = build_charset(opts)
        validate_starting(opts, charset)
    start = time.monotonic_ns()
    try:
        checker = PasswordChecker(opts.inputFile, opts.fileNumber)
        if opts.passwordDictionary is not None:
            found = try_dictionary(checker, opts.passwordDictionary)
        else:
            found = brute_force(checker, charset, opts.minPasswordLen, opts.maxPasswordLen, opts.startingPassword)
    except AppError as e:
        sys.stderr.write(str(e) + "\n")
        raise CliExit(1)
    elapsed = time.monotonic_ns() - start
    sys.stdout.write(f"Time elapsed: {rust_duration(elapsed)}\n")
    if found is None:
        sys.stdout.write("Password not found\n")
    else:
        sys.stdout.write(f"Password found:{found}\n")
    raise CliExit(0)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        opts = parse_args(argv)
        run(opts)
    except CliExit as e:
        return e.code
    except BrokenPipeError:
        return 1

if __name__ == "__main__":
    sys.exit(main())
