    minPasswordLen: int = 1
    maxPasswordLen: int = 10
    fileNumber: int = 0
    startingPassword: str = None
    used_options: list = None


def opt_display(long_name: str) -> str:
    if long_name in LONG_VALUE_NAMES:
        return f"--{long_name} <{LONG_VALUE_NAMES[long_name]}>"
    return f"--{long_name}"


def print_parse_error(message: str, usage: str = None):
    sys.stderr.write(f"error: {message}\n\n")
    if usage is not None:
        sys.stderr.write(f"Usage: {usage}\n\n")
    sys.stderr.write("For more information, try '--help'.\n")


def usage_for_missing(used):
    if not used:
        return "executable --inputFile <inputFile>"
    bits = ["executable", "--inputFile <inputFile>"]
    for name in used:
        if name == "inputFile":
            continue
        if name in LONG_VALUE_NAMES:
            bits.append(opt_display(name))
    return " ".join(bits)


def parse_usize(value: str, long_name: str) -> int:
    disp = opt_display(long_name)
    if value == "" or any(ch < "0" or ch > "9" for ch in value):
        print_parse_error(f"invalid value '{value}' for '{disp}': invalid digit found in string")
        raise CliExit(2)
    try:
        num = int(value, 10)
    except Exception:
        print_parse_error(f"invalid value '{value}' for '{disp}': invalid digit found in string")
        raise CliExit(2)
    if num > (1 << 64) - 1:
        print_parse_error(f"invalid value '{value}' for '{disp}': number too large to fit in target type")
        raise CliExit(2)
    return num


def parse_args(argv):
    raw_values = {}
    seen = set()
    used = []

    def set_value(long_name, val):
        if long_name in seen:
            print_parse_error(f"the argument '{opt_display(long_name)}' cannot be used multiple times", "executable [OPTIONS] --inputFile <inputFile>")
            raise CliExit(2)
        seen.add(long_name)
        used.append(long_name)
        raw_values[long_name] = val

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            if i + 1 < len(argv):
                print_parse_error(f"unexpected argument '{argv[i+1]}' found", "executable [OPTIONS] --inputFile <inputFile>")
            else:
                print_parse_error("unexpected argument '--' found", "executable [OPTIONS] --inputFile <inputFile>")
            raise CliExit(2)
        if arg.startswith("--") and len(arg) > 2:
            body = arg[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                has_attached = True
            else:
                name, val = body, None
                has_attached = False
            if name not in KNOWN_LONG:
                print_parse_error(f"unexpected argument '{arg}' found", "executable [OPTIONS] --inputFile <inputFile>")
                raise CliExit(2)
            if name == "help":
                sys.stdout.write(HELP_TEXT)
                raise CliExit(0)
            if name == "version":
                sys.stdout.write(VERSION_TEXT)
                raise CliExit(0)
            if name in TAKES_VALUE:
                if not has_attached:
                    if i + 1 >= len(argv):
                        print_parse_error(f"a value is required for '{opt_display(name)}' but none was supplied")
                        raise CliExit(2)
                    nxt = argv[i+1]
                    if nxt.startswith("-"):
                        print_parse_error(f"unexpected argument '{nxt}' found", "executable [OPTIONS] --inputFile <inputFile>")
                        raise CliExit(2)
                    val = nxt
                    i += 1
                set_value(name, val)
            i += 1
            continue
        if arg.startswith("-") and arg != "-":
            # clap treats a leading '-' token as an option; for this tool, value-taking
            # short options consume the rest of the token as their value (e.g. -cd).
            flag = arg[1:2]
            rest = arg[2:]
            if flag not in SHORT_TO_LONG:
                print_parse_error(f"unexpected argument '{arg}' found", "executable [OPTIONS] --inputFile <inputFile>")
                raise CliExit(2)
            name = SHORT_TO_LONG[flag]
            if name == "help":
                sys.stdout.write(HELP_TEXT)
                raise CliExit(0)
            if name == "version":
                sys.stdout.write(VERSION_TEXT)
                raise CliExit(0)
            if name in TAKES_VALUE:
                if rest:
                    val = rest[1:] if rest.startswith("=") else rest
                else:
                    if i + 1 >= len(argv):
                        print_parse_error(f"a value is required for '{opt_display(name)}' but none was supplied")
                        raise CliExit(2)
                    nxt = argv[i+1]
                    if nxt.startswith("-"):
                        print_parse_error(f"unexpected argument '{nxt}' found", "executable [OPTIONS] --inputFile <inputFile>")
                        raise CliExit(2)
                    val = nxt
                    i += 1
                set_value(name, val)
            i += 1
            continue
        print_parse_error(f"unexpected argument '{arg}' found", "executable [OPTIONS] --inputFile <inputFile>")
        raise CliExit(2)

    if "inputFile" not in raw_values:
        sys.stderr.write("error: the following required arguments were not provided:\n")
        sys.stderr.write("  --inputFile <inputFile>\n\n")
        sys.stderr.write(f"Usage: {usage_for_missing(used)}\n\n")
        sys.stderr.write("For more information, try '--help'.\n")
        raise CliExit(2)

    opts = Options(used_options=used)
    for k, v in raw_values.items():
        if k in {"workers", "minPasswordLen", "maxPasswordLen", "fileNumber"}:
            setattr(opts, k, parse_usize(v, k))
        else:
            setattr(opts, k, v)
    return opts


def cli_arg_error(msg):
    sys.stderr.write(f"CLI argument error - {msg}\n")
    raise CliExit(1)


def validate_options(opts: Options):
    if not os.path.exists(opts.inputFile):
        cli_arg_error('"\'inputFile\' does not exist"')
    if opts.passwordDictionary is not None and not os.path.exists(opts.passwordDictionary):
        cli_arg_error('"\'passwordDictionary\' does not exist"')
    if opts.charsetFile is not None and not os.path.exists(opts.charsetFile):
        cli_arg_error('"\'charsetFile\' does not exist"')
    if opts.workers is not None and opts.workers == 0:
        cli_arg_error('"\'workers\' must be positive"')
    if opts.minPasswordLen == 0:
        cli_arg_error('"\'minPasswordLen\' must be positive"')
    if opts.maxPasswordLen == 0:
        cli_arg_error('"\'maxPasswordLen\' must be positive"')
    if opts.maxPasswordLen < opts.minPasswordLen:
        cli_arg_error('"\'maxPasswordLen\' must be equal or greater than \'minPasswordLen\'"')
    if opts.passwordDictionary is not None and opts.startingPassword is not None:
        cli_arg_error('"\'startingPassword\' cannot be used with a dictionary file"')


def build_charset(opts: Options):
    if opts.charsetFile is not None:
        try:
            with open(opts.charsetFile, "r", encoding="utf-8") as f:
                return f.read()
        except UnicodeDecodeError:
            with open(opts.charsetFile, "rb") as f:
                return f.read().decode("utf-8", "surrogateescape")
    chars = []
    for ch in opts.charset:
        if ch not in CHARSET_SETS:
            cli_arg_error(f'"Unknown charset option \'{ch}\'"')
        chars.append(CHARSET_SETS[ch])
    return "".join(chars)


def validate_starting(opts: Options, charset: str):
    sp = opts.startingPassword
    if sp is None:
        return
    if len(sp) < opts.minPasswordLen or len(sp) > opts.maxPasswordLen:
        cli_arg_error('"\'startingPassword\' does not respect \'max_password_len\' or \'min_password_len\' configuration"')
    allowed = set(charset)
    for ch in sp:
        if ch not in allowed:
            cli_arg_error('"\'startingPassword\' uses characters out of the generation charset"')


# ZipCrypto primitives -----------------------------------------------------
_CRC_TABLE = []
for _n in range(256):
    _c = _n
    for _ in range(8):
        if _c & 1:
            _c = 0xEDB88320 ^ (_c >> 1)
        else:
            _c >>= 1
    _CRC_TABLE.append(_c & 0xFFFFFFFF)


def _crc32_update(old, byte):
    return ((old >> 8) ^ _CRC_TABLE[(old ^ byte) & 0xFF]) & 0xFFFFFFFF


def _zc_init_keys(password_bytes):
    k0, k1, k2 = 0x12345678, 0x23456789, 0x34567890
    for b in password_bytes:
        k0 = _crc32_update(k0, b)
        k1 = (k1 + (k0 & 0xFF)) & 0xFFFFFFFF
        k1 = (k1 * 134775813 + 1) & 0xFFFFFFFF
        k2 = _crc32_update(k2, (k1 >> 24) & 0xFF)
    return [k0, k1, k2]


def _zc_decrypt_byte(keys):
    temp = (keys[2] | 2) & 0xFFFFFFFF
    return ((temp * (temp ^ 1)) >> 8) & 0xFF


def _zc_update_keys(keys, plain_byte):
    keys[0] = _crc32_update(keys[0], plain_byte)
    keys[1] = (keys[1] + (keys[0] & 0xFF)) & 0xFFFFFFFF
    keys[1] = (keys[1] * 134775813 + 1) & 0xFFFFFFFF
    keys[2] = _crc32_update(keys[2], (keys[1] >> 24) & 0xFF)


def _zc_decrypt_with_keys(keys, data):
    out = bytearray()
    for c in data:
        p = c ^ _zc_decrypt_byte(keys)
        _zc_update_keys(keys, p)
        out.append(p)
    return bytes(out)


def _decompress_zip_member(method, compressed):
    if method == 0:  # stored
        return compressed
    if method == 8:  # deflate, raw stream in ZIP
        return zlib.decompress(compressed, -15)
    if method == 12:  # bzip2
        return bz2.decompress(compressed)
    raise NotImplementedError(method)


class PasswordChecker:
    def __init__(self, zip_path, file_number):
        self.zip_path = zip_path
        try:
            self.zf = zipfile.ZipFile(zip_path, "r")
            infos = self.zf.infolist()
        except zipfile.BadZipFile as e:
            msg = str(e)
            if msg == "File is not a zip file":
                msg = "invalid Zip archive: Could not find EOCD"
            raise AppError(f"Invalid zip file error - {msg}")
        except Exception as e:
            raise AppError(f"Invalid zip file error - {e}")

        if file_number >= len(infos):
            raise AppError(f"File number not found within archive error - '{file_number}'")
        self.info = infos[file_number]
        if not (self.info.flag_bits & 0x1):
            raise AppError(
                f"Invalid zip file error - the selected file in the archive is not encrypted "
                f"(file_number:{file_number} file_name:{self.info.filename})"
            )
        self._load_local_data()
        if self.info.compress_type == 99:
            self.kind = "aes"
            self._setup_aes()
        else:
            self.kind = "zipcrypto"
            self.method = self.info.compress_type
            self.check_byte = ((self.mod_time >> 8) & 0xFF) if (self.info.flag_bits & 0x8) else ((self.info.CRC >> 24) & 0xFF)

    def _load_local_data(self):
        with open(self.zip_path, "rb") as f:
            f.seek(self.info.header_offset)
            hdr = f.read(30)
            if len(hdr) != 30 or hdr[:4] != b"PK\x03\x04":
                raise AppError("Invalid zip file error - invalid local file header")
            (sig, ver, flag, method, mod_time, mod_date, crc, comp_size, uncomp_size,
             name_len, extra_len) = struct.unpack("<IHHHHHIIIHH", hdr)
            self.mod_time = mod_time
            f.seek(name_len + extra_len, os.SEEK_CUR)
            self.encrypted_data = f.read(self.info.compress_size)

    def _setup_aes(self):
        aes = None
        extra = self.info.extra
        pos = 0
        while pos + 4 <= len(extra):
            header_id, size = struct.unpack("<HH", extra[pos:pos+4])
            data = extra[pos+4:pos+4+size]
            if header_id == 0x9901 and len(data) >= 7:
                version = struct.unpack("<H", data[:2])[0]
                vendor = data[2:4]
                strength = data[4]
                actual_method = struct.unpack("<H", data[5:7])[0]
                aes = (version, vendor, strength, actual_method)
                break
            pos += 4 + size
        if aes is None:
            raise AppError("Invalid zip file error - AES extra data not found")
        version, vendor, strength, actual_method = aes
        salt_len_map = {1: 8, 2: 12, 3: 16}
        key_len_map = {1: 16, 2: 24, 3: 32}
        if strength not in salt_len_map:
            raise AppError("Invalid zip file error - unsupported AES strength")
        salt_len = salt_len_map[strength]
        self.aes_key_len = key_len_map[strength]
        data = self.encrypted_data
        if len(data) < salt_len + 2 + 10:
            raise AppError("Invalid zip file error - invalid AES encrypted data")
        self.aes_salt = data[:salt_len]
        self.aes_verifier = data[salt_len:salt_len+2]
        self.aes_ciphertext = data[salt_len+2:-10]
        self.aes_auth = data[-10:]

    def check(self, password: str) -> bool:
        password_bytes = password.encode("utf-8", "surrogateescape")
        if self.kind == "aes":
            return self._check_aes(password_bytes)
        return self._check_zipcrypto(password_bytes)

    def _check_aes(self, password_bytes):
        key_len = self.aes_key_len
        key_material = hashlib.pbkdf2_hmac("sha1", password_bytes, self.aes_salt, 1000, 2 * key_len + 2)
        if key_material[2 * key_len:2 * key_len + 2] != self.aes_verifier:
            return False
        auth_key = key_material[key_len:2 * key_len]
        tag = hmac.new(auth_key, self.aes_ciphertext, hashlib.sha1).digest()[:10]
        return hmac.compare_digest(tag, self.aes_auth)

    def _check_zipcrypto(self, password_bytes):
        data = self.encrypted_data
        if len(data) < 12:
            return False
        keys = _zc_init_keys(password_bytes)
        header = _zc_decrypt_with_keys(keys, data[:12])
        if header[11] != self.check_byte:
            return False
        compressed = _zc_decrypt_with_keys(keys, data[12:])
        try:
            plain = _decompress_zip_member(self.method, compressed)
            if self.info.file_size is not None and len(plain) != self.info.file_size:
                return False
            return (zlib.crc32(plain) & 0xFFFFFFFF) == self.info.CRC
        except Exception:
            # The standard library knows a few ZIP compression formats; use it as a
            # slow validation fallback only after the 1-byte encryption header check.
            try:
                data = self.zf.read(self.info, pwd=password_bytes)
                return (zlib.crc32(data) & 0xFFFFFFFF) == self.info.CRC
            except Exception:
                return False


def rust_duration(ns):
    if ns < 0:
        ns = 0
    sec = ns // 1_000_000_000
    rem = ns % 1_000_000_000
    ms = rem // 1_000_000
    rem %= 1_000_000
    us = rem // 1_000
    n = rem % 1_000
    parts = []
    if sec:
        parts.append(f"{sec}s")
    if ms:
        parts.append(f"{ms}ms")
    if us:
        parts.append(f"{us}us")
    if n or not parts:
        parts.append(f"{n}ns")
    return " ".join(parts)


def read_dictionary_lines(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            s = f.read()
    except UnicodeDecodeError:
        with open(path, "rb") as f:
            s = f.read().decode("utf-8", "surrogateescape")
    if s == "":
        return []
    parts = s.split("\n")
    if s.endswith("\n"):
        parts = parts[:-1]
    return [p[:-1] if p.endswith("\r") else p for p in parts]


def try_dictionary(checker, dict_path):
    for pw in read_dictionary_lines(dict_path):
        if checker.check(pw):
            return pw
    return None


def index_in_charset(password, charset):
    base = len(charset)
    indexes = []
    for ch in password:
        # first occurrence, matching normal iteration when duplicate characters exist
        indexes.append(charset.index(ch))
    n = 0
    for idx in indexes:
        n = n * base + idx
    return n


def candidate_from_index(length, idx, charset):
    base = len(charset)
    chars = [None] * length
    for pos in range(length - 1, -1, -1):
        chars[pos] = charset[idx % base]
        idx //= base
    return "".join(chars)


def brute_force(checker, charset, min_len, max_len, starting=None):
    if len(charset) == 0:
        # The original's worker threads panic for this edge case and ultimately report not found.
        return None
    start_len = len(starting) if starting is not None else None
    for length in range(min_len, max_len + 1):
        if starting is not None:
            if length < start_len:
                continue
            start_idx = index_in_charset(starting, charset) if length == start_len else 0
        else:
            start_idx = 0
        total = len(charset) ** length
        for idx in range(start_idx, total):
            pw = candidate_from_index(length, idx, charset)
            if checker.check(pw):
                return pw
    return None


def run(opts: Options):
    validate_options(opts)
    charset = None
    if opts.passwordDictionary is None:
        charset = build_charset(opts)
        validate_starting(opts, charset)
    start = time.monotonic_ns()
    try:
        checker = PasswordChecker(opts.inputFile, opts.fileNumber)
        if opts.passwordDictionary is not None:
            found = try_dictionary(checker, opts.passwordDictionary)
        else:
            found = brute_force(checker, charset, opts.minPasswordLen, opts.maxPasswordLen, opts.startingPassword)
    except AppError as e:
        sys.stderr.write(str(e) + "\n")
        raise CliExit(1)
    elapsed = time.monotonic_ns() - start
    sys.stdout.write(f"Time elapsed: {rust_duration(elapsed)}\n")
    if found is None:
        sys.stdout.write("Password not found\n")
    else:
        sys.stdout.write(f"Password found:{found}\n")
    raise CliExit(0)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        opts = parse_args(argv)
        run(opts)
    except CliExit as e:
        return e.code
    except BrokenPipeError:
        return 1

if __name__ == "__main__":
    sys.exit(main())
